        // For every upright line with a sibling on its row: how many of its siblings are a column of body text,
        // that is body-class lines at least a quarter as wide as the widest body line of the page. A neighbouring
        // column is that; a table cell, a label beside a value and an initial's neighbour are not (D167).
        int s = 0;
        int e = 0;
        int i = 0;
        int j = 0;
        int m = 0;
        int k = 0;
        while (s < n) {
            e = StRunEnd(ln, s, n);
            m = 0;
            i = s;
            while (i < e) {
                if ((StGet(sf, i, SfkClass()) == body) && (StGet(sf, i, SfkWidth()) > m)) {
                    m = StGet(sf, i, SfkWidth());
                }
                i += 1;
            }
            i = s;
            while (i < e) {
                StPut(sf, i, SfkNcol(), 0);
                if ((StGet(sf, i, SfkUpright()) == 1) && (StGet(sf, i, SfkNsib()) > 0)) {
                    k = 0;
                    j = s;
                    while (j < e) {
                        if ((i != j) && ((StGet(sf, j, SfkClass()) == body) && ((StGet(sf, j, SfkWidth()) * 100) > (m * 25)))) {
                            if (((StMin(StLn(ln, i, Evidence.LhX1()), StLn(ln, j, Evidence.LhX1())) - StMax(StLn(ln, i, Evidence.LhX0()), StLn(ln, j, Evidence.LhX0()))) <= 0) && (((StMin(StLn(ln, i, Evidence.LhY1()), StLn(ln, j, Evidence.LhY1())) - StMax(StLn(ln, i, Evidence.LhY0()), StLn(ln, j, Evidence.LhY0()))) * 10) >= (StMin(StGet(sf, i, SfkHeight()), StGet(sf, j, SfkHeight())) * 3))) {
                                k += 1;
                            }
                        }
                        j += 1;
                    }
                    StPut(sf, i, SfkNcol(), k);
                }
                i += 1;
            }
            s = e;
        }
        return 0;
    }
    public static int StBuild(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells gl, emon.Port.Cells sf, emon.Port.Cells sc, emon.Port.Cells tmp) {
        // The style inventory of the document's lines. `sf`, `sc` and `tmp` are the caller's and are emptied
        // first; afterwards `sf` has a row for every line (see the head of this file), `sc` the classes, and
        // the header says which class is the body, its size, and the document's line gap. Answers the number
        // of classes.
        int n = Evidence.LnCount(ln);
        int l = 0;
        int c = 0;
        int body = -1;
        int total = 0;
        emon.Port.CellsDrop(sf, 0);
        emon.Port.CellsDrop(sc, 0);
        emon.Port.CellsDrop(tmp, 0);
        while (l < SfHdr) {
            emon.Port.CellsPush(sf, 0);
            l += 1;
        }
        emon.Port.CellsSet(sf, SfhLines(), n);
        emon.Port.CellsSet(sf, SfhBody(), -1);
        l = 0;
        while (l < (n * SfStride)) {
            emon.Port.CellsPush(sf, 0);
            l += 1;
        }
        l = 0;
        while (l < n) {
            StLineFeatures(wd, ln, et, gl, sf, l);
            l += 1;
        }
        StNeighbours(ln, sf);
        StClassify(sf, sc, n);
        int nc = emon.Port.CellsLen(sc) / ScStride;
        emon.Port.CellsSet(sf, SfhClasses(), nc);
        c = 0;
        while (c < nc) {
            total += ScGet(sc, c, SckChars());
            if ((body < 0) || (ScGet(sc, c, SckChars()) > ScGet(sc, body, SckChars()))) {
                body = c;
            }
            c += 1;
        }
        emon.Port.CellsSet(sf, SfhChars(), total);
        emon.Port.CellsSet(sf, SfhBody(), body);
        if (body >= 0) {
            emon.Port.CellsSet(sf, SfhSize(), ScGet(sc, body, SckSize()));
            emon.Port.CellsSet(sf, SfhBucket(), ScGet(sc, body, SckBucket()));
            int gap = StLineGap(sf, sc, tmp, n, body);
            emon.Port.CellsSet(sf, SfhGap(), gap);
            StMargins(ln, sf, n, body, ScGet(sc, body, SckSize()));
            StColsibs(ln, sf, n, body);
        }
        return nc;
    }
    public static int StFeatsSize(emon.Port.Cells wd, emon.Port.Cells sf, emon.Port.Cells feats) {
        // Feature column 18 of every text-layer word that has a `feats` row: its size over the document's
        // body size, per-mille (SPEC 8.4.5; P4.2 fills it). Answers the number of words written.
        int n = emon.Port.CellsLen(wd) / 24;
        int bsize = emon.Port.CellsAt(sf, SfhSize());
        int w = 0;
        int k = 0;
        int row = 0;
        if (bsize <= 0) {
            return 0;
        }
        while (w < n) {
            row = Evidence.WdGet(wd, w, Evidence.HdFeat());
            if (row >= 0) {
                Evidence.FeSet(feats, row, Evidence.XtRelSize(), (StSize(Evidence.WdGet(wd, w, Evidence.WfSize())) * 1000) / bsize);
                k += 1;
            }
            w += 1;
        }
        return k;
    }
    public static int SfkHead() {
        return 24;
    }
    public static int SfkUnit() {
        return 25;
    }
    public static int SfkPoints() {
        return 26;
    }
    public static int StSet(emon.Port.Cells sf, int l, int f, int v) {
        // Write a field of a line's row (the heading stage's own fields).
        return StPut(sf, l, f, v);
    }
}
